f not AuroraHub_ALIVE() then speedConn:Disconnect() return end         if not char or not char.Parent or not hum or not hrp or hum.Health <= 0 then return end         if not _G.AuroraHub_SemiTP_SpeedBoost or not isStealBoostLive() then return end         if hum.MoveDirection.Magnitude <= 0 then return end         if hum.FloorMaterial == Enum.Material.Air then return end         local extra = math.max(stealSpeed() - hum.WalkSpeed, 0)         if extra > 0 then             hrp.CFrame = hrp.CFrame + (hum.MoveDirection * extra * dt)         end     end)     table.insert(activeSpeedConnections, speedConn) end  if player.Character then task.spawn(initSpeedFeatures, player.Character) end local speedCharConn speedCharConn = player.CharacterAdded:Connect(function(char)     if not AuroraHub_ALIVE() then speedCharConn:Disconnect() return end     task.wait(0.2)     initSpeedFeatures(char) end)  local STEAL_DURATION = 1.3 local progressFill, percentLabel = nil, nil  local function updateProgressBar(p)     if progressFill then         TweenService:Create(progressFill, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {             Size = UDim2.new(math.clamp(p, 0, 1), 0, 1, 0)         }):Play()     end     if percentLabel then percentLabel.Text = math.floor(math.clamp(p, 0, 1) * 100) .. "%" end end  local findMyBase do     local cached, checkedAt = nil, 0     local function isMine(base)         local sign = base and base.Parent and base:FindFirstChild("PlotSign")         local yourBase = sign and sign:FindFirstChild("YourBase")         return yourBase ~= nil and yourBase.Enabled     end     findMyBase = function()         local now = os.clock()         if cached and now - checkedAt < 2 and cached.Parent then return cached end         if cached and isMine(cached) then checkedAt = now return cached end         cached = nil         local plots = Workspace:FindFirstChild("Plots")         if not plots then return nil end         for _, base in ipairs(plots:GetChildren()) do             if isMine(base) then cached, checkedAt = base, now return base end         end         for _, base in ipairs(plots:GetChildren()) do             if base:IsA("Model") then                 for _, d in ipairs(base:GetDescendants()) do                     if d:IsA("TextLabel") and (string.find(d.Text, player.Name, 1, true) or string.find(d.Text, player.DisplayName, 1, true)) then                         cached, checkedAt = base, now                         return base                     end                 end             end         end         return nil     end end  local function isEnemyPlot(plot)     if not plot or not plot:IsA("Model") then return false end     local sign = plot:FindFirstChild("PlotSign")     local yourBase = sign and sign:FindFirstChild("YourBase")     if yourBase and yourBase.Enabled then return false end     local sg = sign and sign:FindFirstChild("SurfaceGui")     local frame = sg and sg:FindFirstChild("Frame")     local label = frame and frame:FindFirstChild("TextLabel")     if not label or label.Text == "Empty Base" then return false end     local owner = label.Text:gsub("'s [Bb]ase$", ""):gsub("%s+$", "")     return owner ~= player.Name and owner ~= player.DisplayName end  pcall(function()     for _, d in ipairs(Workspace:GetDescendants()) do         if d:IsA("Highlight") and d.Name == "AuroraHub_SemiTP_Podium_Highlight" then             d:Destroy()         end     end end)  local slotHasTarget = true local podiumInfoText = ""  local function readPodiumInfo(podium)     local sp = podium and podium:FindFirstChild("Base") and podium.Base:FindFirstChild("Spawn")     local debris = Workspace:FindFirstChild("Debris")     if not sp or not debris then return "" end     local base = sp.Position     local best, bestD = nil, 7     for _, o in ipairs(debris:GetChildren()) do         if o.Name == "FastOverheadTemplate" and o:IsA("BasePart") then             local p = o.Position             local d = Vector3.new(p.X - base.X, 0, p.Z - base.Z).Magnitude             if d < bestD and p.Y > base.Y - 2 and p.Y < base.Y + 25 then best, bestD = o, d end         end     end     local bb = best and best:FindFirstChild("AnimalOverhead")     if not bb then return "empty" end     local function txt(name)         local l = bb:FindFirstChild(name, true)         return (l and l:IsA("TextLabel") and l.Visible and l.Text ~= "") and l.Text or nil     end     local name, gen, mut = txt("DisplayName"), txt("Generation"), txt("Mutation")     if not name then return "empty" end     return (mut and (mut .. " ") or "") .. name .. (gen and ("  " .. gen) or "") end  local darkBlueHighlight = Instance.new("Highlight") darkBlueHighlight.Name = "AuroraHub_SemiTP_Podium_Highlight" darkBlueHighlight.FillColor = T.ACCENT2 darkBlueHighlight.OutlineColor = T.FILL2 darkBlueHighlight.FillTransparency = 0.35 darkBlueHighlight.OutlineTransparency = 0  local function getTargetPodiumForSlot(slot)     local plots = Workspace:FindFirstChild("Plots")     if not plots then return nil end     local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")     if not hrp then return nil end      local bestPodium, bestScore = nil, math.huge     for _, plot in ipairs(plots:GetChildren()) do         local podiums = (not targetPlot or plot == targetPlot) and isEnemyPlot(plot) and plot:FindFirstChild("AnimalPodiums")         local podium = podiums and podiums:FindFirstChild(tostring(slot))         local spawn = podium and podium:FindFirstChild("Base") and podium.Base:FindFirstChild("Spawn")         local pa = spawn and spawn:FindFirstChild("PromptAttachment")         local prompt = pa and pa:FindFirstChildWhichIsA("ProximityPrompt")         if spawn and prompt then             local score = (hrp.Position - spawn.Position).Magnitude             if not prompt.Enabled then score = score + 100000 end             if score < bestScore then                 bestScore = score                 bestPodium = podium             end         end     end     return bestPodium end  task.spawn(function()     while task.wait(0.25) do         if not AuroraHub_ALIVE() then darkBlueHighlight:Destroy() return end         local targetPodium = getTargetPodiumForSlot(selectedSlot)         slotHasTarget = targetPodium ~= nil         podiumInfoText = targetPodium and readPodiumInfo(targetPodium) or "no enemy base has this podium"         if targetPodium then             if darkBlueHighlight.Adornee ~= targetPodium or darkBlueHighlight.Parent ~= targetPodium then                 darkBlueHighlight.Adornee = targetPodium                 darkBlueHighlight.Parent = targetPodium             end         else             darkBlueHighlight.Adornee = nil             darkBlueHighlight.Parent = nil         end     end end)  local function getNearestDeliveryHitbox()     local myBase = findMyBase()     if not myBase then return nil end     local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")     local refPos = hrp and hrp.Position or myBase:GetPivot().Position      local nearestPos = nil     local minDist = math.huge     for _, d in pairs(myBase:GetDescendants()) do         if d.Name == "DeliveryHitbox" then             local pos = d:IsA("BasePart") and d.Position or (d:IsA("Model") and d:GetPivot().Position)             if pos then                 local dist = (pos - refPos).Magnitude                 if dist < minDist then                     minDist = dist                     nearestPos = pos                 end             end         end     end      if not nearestPos then         for _, d in pairs(Workspace:GetDescendants()) do             if d.Name == "DeliveryHitbox" then                 local pos = d:IsA("BasePart") and d.Position or (d:IsA("Model") and d:GetPivot().Position)                 if pos then                     local dist = (pos - refPos).Magnitude                     if dist < minDist then                         minDist = dist                         nearestPos = pos

